import { documentTaskPrompt } from './carb-document-evidence.js';
import path from 'node:path';
import { lstat } from 'node:fs/promises';
import { z } from 'zod';

function validOutputName(name) {
  return /^[^<>:"/\\|?*\x00-\x1f]+\.md$/iu.test(name) &&
    !name.startsWith('.') && !/^(?:con|prn|aux|nul|com[1-9¹²³]|lpt[1-9¹²³])(?:\.|$)/iu.test(name);
}

export const documentWorkflowMethods = {
  'workflows.startDocument': {
    params: z.object({
      projectPath: z.string().min(1).max(4096),
      connectionId: z.string().min(1).max(256),
      model: z.string().trim().min(1).max(500),
      instructions: z.string().trim().min(1).max(8000),
      role: z.string().trim().max(240).optional(),
      acceptanceCriteria: z.string().trim().max(3000).optional(),
      outputName: z.string().trim().max(140).refine(validOutputName, 'Choose a valid Markdown filename ending in .md.'),
    }),
    result: z.object({ threadId: z.string(), turnId: z.string() }),
  },
};

export async function startDocumentWorkflow({ store, orchestrator, modelConnections, workspaceForRequest, onStart }, request) {
  const workspacePath = workspaceForRequest(store, request);
  const { outputName, model, connectionId, instructions } = request;
  // Fail early for an existing output. The runtime also creates the file
  // exclusively, in case another workflow creates it between here and the write.
  try {
    await lstat(path.join(workspacePath, outputName));
    throw new Error('A file with that name already exists. Choose a new output filename.');
  } catch (error) {
    if (error.code !== 'ENOENT') throw error;
  }
  modelConnections.resolveForRuntime(connectionId);
  const settings = { provider: 'api', connectionId, model, approval: 'ask' };
  const thread = await orchestrator.startThread('api', request.projectPath, { ...settings, documentOutput: outputName });
  try {
    onStart(thread.id);
    store.setThreadSettings(thread.id, settings);
    store.renameThread(thread.id, outputName);
    const prompt = documentTaskPrompt(request);
    const result = await orchestrator.submitTurn(thread.id, prompt, [], { model });
    if (result.queued) throw new Error('The document task could not start immediately.');
    return { threadId: thread.id, turnId: result.turnId };
  } catch (error) {
    await orchestrator.close(thread.id).catch(() => undefined);
    throw error;
  }
}
